def transform(g):
    h,w=len(g),len(g[0])
    o=[row[:] for row in g]
    top=[(j,g[0][j]) for j in range(w) if g[0][j]!=0]
    topset={(0,j) for j,_ in top}
    edges={}
    for i in range(h):
        for j in range(w):
            c=g[i][j]
            if c and (i,j) not in topset:
                edges.setdefault(c,[]).append((i,j))
    for j,c in top:
        ei=edges.get(c,[])
        if ei:
            i2,j2=ei[0]
            for i in range(0,i2+1): o[i][j]=c
            for jj in range(min(j,j2),max(j,j2)+1): o[i2][jj]=c
        else:
            for i in range(0,h): o[i][j]=c
    return o

